"""Analytical repetition-cat Pauli channel with finite physical saturation."""

import math
from dataclasses import dataclass


@dataclass(frozen=True)
class Parameters:
    distance: int
    photons: float
    kappa_2: float
    kappa_1: float = 100.0

    def __post_init__(self) -> None:
        if (
            type(self.distance) is not int
            or self.distance < 3
            or self.distance % 2 == 0
        ):
            raise ValueError(
                "The repetition distance must be an odd integer at least three"
            )
        if not all(
            math.isfinite(value) for value in (self.photons, self.kappa_1, self.kappa_2)
        ):
            raise ValueError("Cat processor parameters must be finite")
        if self.photons < 4 or self.kappa_1 < 10 or self.kappa_2 <= 0:
            raise ValueError(
                "The analytical cat model requires photons>=4 and kappa_1>=10"
            )
        if not 1e-7 <= self.kappa_1 / self.kappa_2 <= 1e-1:
            raise ValueError("The physical loss ratio must lie in [1e-7, 1e-1]")

    @property
    def gate_seconds(self) -> float:
        return 5 * self.distance / self.kappa_2

    @property
    def pauli_probabilities(self) -> tuple[float, float, float, float]:
        """Exponentiate the bit/phase flip rates instead of clipping linearized rates."""
        bit_rate = (self.distance - 1) * self.distance * math.exp(-2 * self.photons)
        phase_rate = (
            0.056
            * self.distance
            * (self.photons**0.86 * self.kappa_1 / self.kappa_2 / 0.013)
            ** (0.5 * (self.distance + 1))
        )
        bit = -math.expm1(-2 * bit_rate) / 2
        phase = -math.expm1(-2 * phase_rate) / 2
        return (
            (1 - bit) * (1 - phase),
            bit * (1 - phase),
            bit * phase,
            (1 - bit) * phase,
        )

"""Original seven-bit SWAP test with exact real-amplitude rotations."""

import math

import numpy as np
import torch

import flagquantum as fq

from .synthesis import approximate


def amplitudes() -> tuple[float, ...]:
    values = 1 - 2 * np.random.RandomState(12).rand(8)
    values /= np.linalg.norm(values)
    return tuple(float(value) for value in values)


def controlled_y(circuit: fq.Circuit, control: int, target: int, angle: float) -> None:
    circuit.ry(target, theta=angle / 2)
    circuit.cx(control, target)
    circuit.ry(target, theta=-angle / 2)
    circuit.cx(control, target)


def prepare(
    circuit: fq.Circuit, wires: tuple[int, int, int], values: tuple[float, ...]
) -> None:
    if (
        len(values) != 8
        or not all(math.isfinite(value) for value in values)
        or abs(sum(value * value for value in values) - 1) > 1e-12
    ):
        raise ValueError("The source input requires eight normalized real amplitudes")
    if len(set(wires)) != 3 or any(not 0 <= wire < circuit.n_qubits for wire in wires):
        raise ValueError("Preparation wires must be distinct and within the circuit")
    for depth in range(3):
        stride = 1 << (3 - depth)
        for prefix in range(1 << depth):
            branch = values[prefix * stride : (prefix + 1) * stride]
            half = stride // 2
            if depth == 2:
                left, right = branch
            else:
                left = math.sqrt(sum(value * value for value in branch[:half]))
                right = math.sqrt(sum(value * value for value in branch[half:]))
            angle = 2 * math.atan2(right, left)
            negative = tuple(
                wires[index]
                for index in range(depth)
                if not ((prefix >> (depth - index - 1)) & 1)
            )
            for wire in negative:
                circuit.x(wire)
            if depth == 0:
                circuit.ry(wires[0], theta=angle)
            elif depth == 1:
                controlled_y(circuit, wires[0], wires[1], angle)
            else:
                first, second, target = wires
                controlled_y(circuit, second, target, angle / 2)
                circuit.cx(first, second)
                controlled_y(circuit, second, target, -angle / 2)
                circuit.cx(first, second)
                controlled_y(circuit, first, target, angle / 2)
            for wire in reversed(negative):
                circuit.x(wire)


def swap_test() -> fq.Circuit:
    circuit = fq.Circuit(7, dtype=torch.complex128)
    values = amplitudes()
    prepare(circuit, (1, 2, 3), values)
    prepare(circuit, (4, 5, 6), values)
    circuit.h(0)
    for first, second in zip((1, 2, 3), (4, 5, 6), strict=True):
        circuit.cx(second, first)
        circuit.ccx(0, first, second)
        circuit.cx(second, first)
    circuit.h(0)
    return circuit


def synthesize(
    circuit: fq.Circuit, iterations: int
) -> tuple[fq.Circuit, tuple[float, ...]]:
    """Approximate each uncontrolled RY/RX; preserve every native entangling gate."""
    result = fq.Circuit(int(circuit.n_qubits), dtype=torch.complex128)
    errors = []
    for instruction in circuit.to_ir().instructions:
        if instruction.name in ("rx", "ry"):
            angle = float(instruction.params["theta"])
            axis = 1 if instruction.name == "rx" else 2
            quaternion = np.zeros(4, dtype=np.float64)
            quaternion[0], quaternion[axis] = math.cos(angle / 2), math.sin(angle / 2)
            fitted = approximate(quaternion, iterations)
            errors.append(fitted.error)
            for name in fitted.word:
                result.gate(name, instruction.wires)
        elif instruction.name in ("h", "x", "cx", "ccx"):
            result.gate(instruction.name, instruction.wires)
        else:
            raise ValueError(
                "The source compilation path requires RY/RX and native Clifford controls"
            )
    return result, tuple(errors)

"""Example-local SU(2) Solovay--Kitaev words with measured operator errors."""

from dataclasses import dataclass
from functools import lru_cache

import numpy as np
from numpy.typing import NDArray

Quaternion = NDArray[np.float64]
Word = tuple[str, ...]


def product(first: Quaternion, second: Quaternion) -> Quaternion:
    return np.concatenate(
        (
            np.array([first[0] * second[0] - first[1:] @ second[1:]]),
            first[0] * second[1:]
            + second[0] * first[1:]
            + np.cross(first[1:], second[1:]),
        )
    )


def inverse(value: Quaternion) -> Quaternion:
    result: Quaternion = value * np.array([1, -1, -1, -1])
    return result


def adjoint_word(word: Word) -> Word:
    names = {"h": "h", "t": "tdg", "tdg": "t"}
    return tuple(names[name] for name in reversed(word))


def canonical(value: Quaternion) -> Quaternion:
    nonzero = np.flatnonzero(np.abs(value) > 1e-12)
    return -value if nonzero.size and value[nonzero[0]] < 0 else value


GATES = {
    "h": np.array([0.0, -1 / np.sqrt(2), 0.0, -1 / np.sqrt(2)]),
    "t": np.array([np.cos(np.pi / 8), 0.0, 0.0, np.sin(np.pi / 8)]),
    "tdg": np.array([np.cos(np.pi / 8), 0.0, 0.0, -np.sin(np.pi / 8)]),
}


@lru_cache(maxsize=1)
def net() -> tuple[NDArray[np.float64], tuple[Word, ...]]:
    identity = np.array([1.0, 0.0, 0.0, 0.0])
    rows: dict[tuple[float, ...], tuple[Quaternion, Word]] = {
        tuple(identity): (identity, ())
    }
    frontier: list[tuple[Quaternion, Word]] = [(identity, ())]
    for _ in range(12):
        next_frontier: list[tuple[Quaternion, Word]] = []
        for value, word in frontier:
            for name, gate in GATES.items():
                candidate = canonical(product(gate, value))
                key = tuple(np.round(candidate, 10))
                if key not in rows:
                    entry = (candidate, word + (name,))
                    rows[key] = entry
                    next_frontier.append(entry)
        frontier = next_frontier
    values, words = zip(*rows.values(), strict=True)
    return np.stack(values), tuple(words)


def balanced(value: Quaternion) -> tuple[Quaternion, Quaternion]:
    value = value / np.linalg.norm(value)
    if value[0] < 0:
        value = -value
    magnitude = float(np.linalg.norm(value[1:]))
    if magnitude < 1e-14:
        identity = np.array([1.0, 0.0, 0.0, 0.0])
        return identity, identity
    deficit = 1 - float(value[0])
    if deficit <= 0:
        deficit = magnitude * magnitude / (1 + float(value[0]))
    sine = (deficit / 2) ** 0.25
    cosine = np.sqrt(1 - sine * sine)
    first = np.array([cosine, sine, 0.0, 0.0])
    second = np.array([cosine, 0.0, sine, 0.0])
    commutator = product(
        product(product(first, second), inverse(first)), inverse(second)
    )
    a = commutator[1:] / np.linalg.norm(commutator[1:])
    b = value[1:] / magnitude
    dot = float(np.clip(a @ b, -1, 1))
    if dot < -1 + 1e-12:
        axis = np.cross(a, np.array([1.0, 0.0, 0.0]))
        if np.linalg.norm(axis) < 1e-12:
            axis = np.cross(a, np.array([0.0, 1.0, 0.0]))
        rotation = np.concatenate((np.array([0.0]), axis / np.linalg.norm(axis)))
    else:
        rotation = np.concatenate((np.array([1 + dot]), np.cross(a, b)))
        rotation /= np.linalg.norm(rotation)
    return (
        product(product(rotation, first), inverse(rotation)),
        product(product(rotation, second), inverse(rotation)),
    )


@dataclass(frozen=True)
class Approximation:
    word: Word
    quaternion: Quaternion
    iterations: int
    error: float


def _nearest_index(overlaps: Quaternion) -> int:
    # Equivalent words can differ by BLAS roundoff. Resolve overlap ties in
    # insertion order at the same 1e-12 precision used to validate the target.
    return int(np.argmax(np.round(np.abs(overlaps), 12)))


def approximate(value: Quaternion, iterations: int) -> Approximation:
    """Return actual H/T/Tdg words; errors are computed, never assumed from depth."""
    if type(iterations) is not int or not 0 <= iterations <= 3:
        raise ValueError("This source experiment admits zero to three SK iterations")
    if value.shape != (4,) or not np.isfinite(value).all():
        raise ValueError("The target must be a finite unit quaternion")
    if abs(float(np.linalg.norm(value)) - 1) > 1e-12:
        raise ValueError("The target quaternion must have unit norm")
    values, words = net()

    def recurse(target: Quaternion, depth: int) -> tuple[Quaternion, Word]:
        if depth == 0:
            overlaps = values @ target
            index = _nearest_index(overlaps)
            chosen = values[index] * (1 if overlaps[index] >= 0 else -1)
            return chosen, words[index]
        previous, word = recurse(target, depth - 1)
        delta = product(target, inverse(previous))
        v, w = balanced(delta)
        v_approx, v_word = recurse(v, depth - 1)
        w_approx, w_word = recurse(w, depth - 1)
        result = product(
            product(
                product(product(v_approx, w_approx), inverse(v_approx)),
                inverse(w_approx),
            ),
            previous,
        )
        # Matrix products act right to left; these words are chronological.
        return (
            result,
            word + adjoint_word(w_word) + adjoint_word(v_word) + w_word + v_word,
        )

    actual, word = recurse(value, iterations)
    error = min(
        float(np.linalg.norm(actual - value)), float(np.linalg.norm(actual + value))
    )
    return Approximation(word, actual, iterations, error)

"""Compose every logical clock's cat noise into bounded native qubit channels."""

import math
from dataclasses import dataclass

import numpy as np
import torch
from numpy.typing import NDArray

import flagquantum as fq
from flagquantum.noise import KrausChannel, NoiseModel, noisy_density_matrix

from .noise import Parameters

ComplexArray = NDArray[np.complex128]
RealArray = NDArray[np.float64]
PAULIS = np.array(
    [np.eye(2), [[0, 1], [1, 0]], [[0, -1j], [1j, 0]], [[1, 0], [0, -1]]],
    dtype=np.complex128,
)


@dataclass(frozen=True)
class Execution:
    density: torch.Tensor
    clocks: int
    source_instructions: int
    one_qubit_noise_applications: int
    merged_channels: int


def rotation(name: str) -> RealArray:
    matrices = {
        "i": np.eye(2, dtype=np.complex128),
        "h": np.array([[1, 1], [1, -1]], dtype=np.complex128) / math.sqrt(2),
        "x": PAULIS[1],
        "z": PAULIS[3],
        "s": np.diag([1, 1j]),
        "sdg": np.diag([1, -1j]),
        "t": np.diag([1, np.exp(1j * np.pi / 4)]),
        "tdg": np.diag([1, np.exp(-1j * np.pi / 4)]),
    }
    matrix = matrices[name]
    return np.array(
        [
            [np.trace(a @ matrix @ b @ matrix.conj().T).real / 2 for b in PAULIS[1:]]
            for a in PAULIS[1:]
        ],
        dtype=np.float64,
    )


def kraus(transfer: RealArray, name: str) -> KrausChannel:
    """Convert an unital Bloch transfer to its exact two-dimensional Choi channel."""
    choi = np.kron(PAULIS[0].T, PAULIS[0])
    for index, source in enumerate(PAULIS[1:]):
        output = sum(
            (transfer[row, index] * PAULIS[row + 1] for row in range(3)),
            np.zeros((2, 2), dtype=np.complex128),
        )
        choi += np.kron(source.T, output)
    choi /= 2
    values, vectors = np.linalg.eigh(choi)
    if float(values.min()) < -1e-11:
        raise ValueError("The composed cat channel is not completely positive")
    operators = tuple(
        torch.from_numpy(
            np.sqrt(max(float(value), 0.0)) * vectors[:, index].reshape(2, 2).T.copy()
        )
        for index, value in enumerate(values)
        if value > 0
    )
    effect = sum(
        (operator.mH @ operator for operator in operators),
        torch.zeros((2, 2), dtype=torch.complex128),
    )
    if float((effect - torch.eye(2, dtype=torch.complex128)).abs().max()) > 1e-10:
        raise ValueError("The composed cat channel lost trace preservation")
    return KrausChannel(name, operators)


def execute(circuit: fq.Circuit, parameters: Parameters) -> Execution:
    """Keep all ASAP clocks, including preparation, readout and idle-wire correction."""
    width = int(circuit.n_qubits)
    instructions = circuit.to_ir().instructions
    layers: list[list[tuple[str, tuple[int, ...]]]] = []
    ready = [0] * width
    for instruction in instructions:
        name, wires = instruction.name, instruction.wires
        if name not in ("h", "x", "z", "s", "sdg", "t", "tdg", "cx", "ccx"):
            raise ValueError(
                "The logical cat execution requires discrete native instructions"
            )
        layer = max(ready[wire] for wire in wires)
        while len(layers) <= layer:
            layers.append([])
        layers[layer].append((name, wires))
        for wire in wires:
            ready[wire] = layer + 1
    # Every preparation starts in |0>; an identity followed by the p0 channel is exact.
    layers = [[("i", (wire,)) for wire in range(width)], *layers, [("i", (0,))]]
    probabilities = parameters.pauli_probabilities
    diagonal = np.diag(
        [
            1 - 2 * (probabilities[2] + probabilities[3]),
            1 - 2 * (probabilities[1] + probabilities[3]),
            1 - 2 * (probabilities[1] + probabilities[2]),
        ]
    )
    pending = [np.eye(3, dtype=np.float64) for _ in range(width)]
    rotations = {
        name: rotation(name) for name in ("i", "h", "x", "z", "s", "sdg", "t", "tdg")
    }
    native = fq.Circuit(width, dtype=torch.complex128)
    noise = NoiseModel()
    merged = 0

    def flush() -> None:
        nonlocal merged
        for wire in range(width):
            label = f"cat_clock_block_{merged}"
            native.any(wire, matrix=torch.eye(2, dtype=torch.complex128), name=label)
            noise.add(label, kraus(pending[wire], label))
            pending[wire] = np.eye(3, dtype=np.float64)
            merged += 1

    for layer in layers:
        entangling = [(name, wires) for name, wires in layer if len(wires) > 1]
        if entangling:
            flush()
            for name, wires in entangling:
                native.gate(name, wires)
        active = {wires[0]: name for name, wires in layer if len(wires) == 1}
        for wire in range(width):
            pending[wire] = diagonal @ rotations[active.get(wire, "i")] @ pending[wire]
    flush()
    density = noisy_density_matrix(native, noise, dtype=torch.complex128).reshape(
        1 << width, 1 << width
    )
    if abs(complex(density.trace()) - 1) > 1e-9:
        raise ValueError("The complete native cat simulation lost total probability")
    return Execution(
        density, len(layers), len(instructions), width * len(layers), merged
    )
